if(String($env.MP_COMMERCE_FULFILLMENT_ENABLED||'')!=='true') throw new Error('Woo fulfillment disabled');
const p=$json.body||$json;p.provider='woocommerce';p.site_key='danks.store';
if(p.external_order_id && !/^[1-9][0-9]*$/.test(String(p.external_order_id))) throw new Error('Numeric Woo order ID required');
if(p.product_code) {
 const product=decodeURIComponent(String(p.product_code)).match(/(?:PROD|LOT)-[A-Za-z0-9-]+/);
 if(!product) throw new Error('Scan a Product or sellable whole Lot QR.');
 p.product_code=product[0];
}
return [{json:{payload:Buffer.from(JSON.stringify(p)).toString('base64'),order_id:String(p.external_order_id||'')}}];

